begin;
select plan(32);
select has_function('graftvision_private','save_model_region',array['uuid','uuid','uuid','text','jsonb','boolean','integer','integer','uuid'],'typed region save exists');
select policies_are('public','model_annotation_region_version',array[]::name[],'region versions deny normal users');
select policies_are('public','model_annotation_region_current',array[]::name[],'region pointers deny normal users');
select throws_ok($$insert into public.model_annotation_region_version(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,region_code,boundary_points,closed,revision,created_by) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),1,'crown_region','[]'::jsonb,true,1,gen_random_uuid())$$,null,null,'direct region-version mutation is blocked');
select throws_ok($$insert into public.model_annotation_region_current(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,normalization_version,region_code,current_version_id,updated_by) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),1,'graftvision-model-normalization-v1','crown_region',gen_random_uuid(),gen_random_uuid())$$,null,null,'direct region-pointer mutation is blocked');
select ok(position('frontal_recipient_region' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'recipient code accepted');
select ok(position('mid_scalp_region' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'mid-scalp code accepted');
select ok(position('crown_region' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'crown code accepted');
select ok(position('left_temporal_region' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'temporal codes accepted');
select ok(position('donor_rear_region' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'donor codes accepted');
select ok(position('exclusion_region' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'exclusion code accepted');
select ok(position('p_region_code not in' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'unknown region codes rejected');
select ok(position('n<4' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'fewer than four points rejected');
select ok(position('n>128' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'more than 128 points rejected');
select ok(position('not p_closed' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'open regions rejected');
select ok(position('count(distinct x->>''id'')' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'duplicate point IDs rejected');
select ok(position('count(distinct (x->>''order_index'')::integer)' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'duplicate order indexes rejected');
select ok(position('MODEL_REGION_INVALID' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'skipped order indexes are rejected as malformed region input');
select ok(position('^(0|[1-9][0-9]*)$' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'negative order indexes rejected');
select ok(position('-2 and 2' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'coordinate bounds enforced');
select ok(position('p_points->0->>''x''' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'repeated closure coordinate rejected');
select ok(position('require_scan_capture_context' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'wrong clinic denied through trusted context');
select ok(position('is_assigned_verified_doctor' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'wrong Doctor and Assistant denied');
select ok(position('p.package_state<>''draft''' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'finalized package denied');
select ok(position('MODEL_REGION_POINTER_CONFLICT' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'stale pointer rejected');
select ok(position('p.revision<>p_expected_package_revision' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'stale package rejected');
select ok(position('MODEL_REGION_IDEMPOTENCY_MISMATCH' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'changed-payload replay rejected');
select ok(position('model_annotation_region_version' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'immutable region versions appended');
select ok(position('prior_version_id=model_annotation_region_current.current_version_id' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'current pointer preserves prior version');
select ok(position('model.region_saved' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'approved audit action emitted');
select ok(position('storage_key' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))=0,'audit excludes storage paths');
select ok(position('boundary_points' in pg_get_functiondef('graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid)'::regprocedure))>0,'points remain in immutable version data');
select * from finish(); rollback;
